#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# CGPA Pilot - v1.0.16 updater (Mac / Linux / WSL)
#
#   Double-click me, or in a terminal run:   bash apply-v1.0.16.sh
#
#   This file carries the whole v1.0.16 patch inside it. It will:
#     1. check you are inside the CGPA-pilot folder and main is up to date
#     2. refuse to run if you have OTHER uncommitted work (I never touch it)
#     3. apply the v1.0.16 patch, commit it, and push it to main
#
#   WHAT THIS FIXES (the 4 live bugs):
#     - AI falsely telling students "no internet" while their connection is
#       fine (the cross-origin stream was missing CORS headers). Students now
#       get the TRUE reason (offline vs AI service problem), and student-side
#       failures now reach the admin error log.
#     - AI Monitor stuck on "Loading error log..." forever - it now shows the
#       real problem with a Retry button, and the log endpoint never 500s.
#     - Admin-enlarged icons SHIFTING in the student view - every icon slot
#       (header, tool tiles, privacy, Sky Dash, landing) now increases in size
#       IN PLACE: the slot grows with the icon, so size and width increase
#       without shifting, clipping or overlapping the text.
#     - Publish failing with a blank 500 that diagnostics missed - publish
#       failures now explain themselves (size limits, real database error),
#       and diagnostics dry-run the publish path so "all healthy" can never
#       coexist with a broken publish.
# -----------------------------------------------------------------------------
set -u
cd "$(dirname "$0")" || exit 1

echo "============================================"
echo " CGPA Pilot updater - v1.0.16"
echo " (AI errors that tell the truth + publish that"
echo "  explains itself + icons that grow in place)"
echo "============================================"
echo
[ -f package.json ] || {
  echo " ERROR: put this file INSIDE your CGPA-pilot folder"
  echo " (the folder that contains package.json), then run it again."
  exit 1
}
command -v git >/dev/null 2>&1 || { echo " ERROR: git is not installed."; exit 1; }
echo " Repo folder: $PWD"
echo

# --- Safety: never touch other uncommitted work ---
# (old updater files v1.0.12-v1.0.16 are ignored - they are mine, not yours)
if [ -n "$(git status --porcelain | grep -v -e 'apply-v1.0.12.sh' -e 'fix-cgpa-v1.0.12.bat' -e 'v1.0.12.patch' -e '.v1012' -e 'apply-v1.0.13.sh' -e 'fix-cgpa-v1.0.13.bat' -e 'v1.0.13.patch' -e '.v1013' -e 'apply-v1.0.14.sh' -e 'fix-cgpa-v1.0.14.bat' -e 'v1.0.14.patch' -e '.v1014' -e 'apply-v1.0.15.sh' -e 'fix-cgpa-v1.0.15.bat' -e 'v1.0.15.patch' -e '.v1015' -e 'apply-v1.0.16.sh' -e 'v1.0.16.patch' -e '.v1016' | head -n 1)" ]; then
  echo " STOP - this folder has other uncommitted changes:"
  git status --short
  echo
  echo " I never touch your work. Commit or stash those first, then run me again."
  exit 1
fi

echo " Checking main is up to date..."
git checkout main || exit 1
git pull origin main || { echo; echo " Could not update from GitHub - check your internet connection."; exit 1; }

# --- Already applied? ---
if [ -f test/aiChatError.test.mjs ] && grep -q 'service-error' src/services/aiChat.ts; then
  echo
  echo " v1.0.16 is already applied - nothing to do. You are up to date."
  exit 0
fi

# --- This update builds on v1.0.15 (the CGPA History journey fix) ---
if [ ! -f src/services/historyProgress.ts ]; then
  echo
  echo ' This update builds on v1.0.15.'
  echo ' Please run apply-v1.0.15.sh first (it is in this folder),'
  echo ' then run me again.'
  exit 1
fi

echo
echo " Preparing the v1.0.16 patch (embedded in this file)..."
rm -f .v1016.b64 .v1016.patch
